-- Fase 2.3: esquema incremental preparado; NO APLICAR sin autorización PostgreSQL.
CREATE TYPE "EmploymentStatus" AS ENUM ('ACTIVE','INACTIVE');
CREATE TYPE "AssignmentStatus" AS ENUM ('ACTIVE','INACTIVE','CANCELED');
CREATE TYPE "WorkShiftStatus" AS ENUM ('SCHEDULED','CANCELED');
CREATE TABLE "employees" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"employee_code" VARCHAR(64) NOT NULL,"display_name" VARCHAR(160) NOT NULL,"status" "EmploymentStatus" NOT NULL DEFAULT 'ACTIVE',"user_id" UUID,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "employees_pkey" PRIMARY KEY("id"));
CREATE TABLE "employee_branch_assignments" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"employee_id" UUID NOT NULL,"branch_id" UUID NOT NULL,"status" "AssignmentStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "employee_branch_assignments_pkey" PRIMARY KEY("id"));
CREATE TABLE "work_shifts" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"branch_id" UUID NOT NULL,"scheduled_start" TIMESTAMPTZ(6) NOT NULL,"scheduled_end" TIMESTAMPTZ(6) NOT NULL,"status" "WorkShiftStatus" NOT NULL DEFAULT 'SCHEDULED',"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "work_shifts_pkey" PRIMARY KEY("id"));
CREATE TABLE "work_shift_assignments" ("id" UUID NOT NULL,"work_shift_id" UUID NOT NULL,"employee_id" UUID NOT NULL,"organization_id" UUID NOT NULL,"branch_id" UUID NOT NULL,"status" "AssignmentStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "work_shift_assignments_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "employees_organization_id_employee_code_key" ON "employees"("organization_id","employee_code"); CREATE UNIQUE INDEX "employees_id_organization_id_key" ON "employees"("id","organization_id"); CREATE UNIQUE INDEX "employees_user_id_key" ON "employees"("user_id"); CREATE UNIQUE INDEX "employee_branch_assignments_employee_id_branch_id_key" ON "employee_branch_assignments"("employee_id","branch_id"); CREATE UNIQUE INDEX "work_shifts_id_organization_id_branch_id_key" ON "work_shifts"("id","organization_id","branch_id"); CREATE UNIQUE INDEX "work_shift_assignments_work_shift_id_employee_id_key" ON "work_shift_assignments"("work_shift_id","employee_id");
ALTER TABLE "employees" ADD CONSTRAINT "employees_organization_id_fkey" FOREIGN KEY("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT; ALTER TABLE "employees" ADD CONSTRAINT "employees_user_id_fkey" FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE RESTRICT; ALTER TABLE "employee_branch_assignments" ADD CONSTRAINT "employee_branch_assignments_employee_org_fkey" FOREIGN KEY("employee_id","organization_id") REFERENCES "employees"("id","organization_id") ON DELETE RESTRICT; ALTER TABLE "employee_branch_assignments" ADD CONSTRAINT "employee_branch_assignments_branch_org_fkey" FOREIGN KEY("branch_id","organization_id") REFERENCES "branches"("id","organization_id") ON DELETE RESTRICT; ALTER TABLE "work_shifts" ADD CONSTRAINT "work_shifts_branch_org_fkey" FOREIGN KEY("branch_id","organization_id") REFERENCES "branches"("id","organization_id") ON DELETE RESTRICT; ALTER TABLE "work_shifts" ADD CONSTRAINT "work_shifts_time_check" CHECK ("scheduled_end" > "scheduled_start"); ALTER TABLE "work_shift_assignments" ADD CONSTRAINT "work_shift_assignments_shift_scope_fkey" FOREIGN KEY("work_shift_id","organization_id","branch_id") REFERENCES "work_shifts"("id","organization_id","branch_id") ON DELETE RESTRICT; ALTER TABLE "work_shift_assignments" ADD CONSTRAINT "work_shift_assignments_employee_org_fkey" FOREIGN KEY("employee_id","organization_id") REFERENCES "employees"("id","organization_id") ON DELETE RESTRICT;
